def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)

    if not alive_opps:
        base = DAILY_SALARY * 0.28
        if no_water >= 1 or hp <= 3:
            base = DAILY_SALARY * 0.6
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    opp_desperation = 0
    rich_count = 0
    for opp in alive_opps:
        if opp.get('budget', 0) >= 300:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            opp_desperation += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.3
    if no_water >= 2:
        urgency += 0.6
    elif no_water >= 1:
        urgency += 0.3

    market_pressure = 0.0
    if highest_prev >= 130:
        market_pressure = 0.5
    elif highest_prev >= 100:
        market_pressure = 0.35
    elif highest_prev >= 70:
        market_pressure = 0.2
    elif highest_prev > 0:
        market_pressure = 0.1

    base = DAILY_SALARY * (0.22 + 0.22 * scarcity + urgency + market_pressure)

    if supply >= 22 and urgency < 0.5:
        base *= 0.72
    elif supply <= 17:
        base *= 1.18

    if opp_desperation >= 2:
        base *= 1.12
    if rich_count >= 2:
        base *= 1.08

    if highest_prev > 0:
        if urgency >= 0.5:
            target = max(base, highest_prev + 2.5)
        else:
            if highest_prev >= 120:
                target = min(base, DAILY_SALARY * 0.62)
            else:
                target = max(base, avg_prev * 0.82)
    else:
        target = base

    if day >= 8 and budget > DAILY_SALARY * 3:
        target *= 1.08

    reserve = 0.0
    if hp > 4 and no_water == 0:
        reserve = DAILY_SALARY * 0.35
    elif hp > 2:
        reserve = DAILY_SALARY * 0.15

    max_affordable = max(0.0, budget - reserve)
    if urgency >= 0.8:
        max_affordable = budget

    bid = min(target, max_affordable)

    if urgency >= 0.8:
        bid = max(bid, DAILY_SALARY * 0.92)
    elif urgency >= 0.45:
        bid = max(bid, DAILY_SALARY * 0.68)

    bid = max(0.0, min(budget, bid))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    # Alive opponents and yesterday bids
    alive_opps = []
    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            if prev and prev.get('bid') is not None:
                try:
                    yesterday_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    # If no info, default conservative
    if not alive_opps:
        cap = min(budget, DAILY_SALARY * 0.4)
        return max(0.0, cap)

    # Pressure estimate from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Determine how many allocations are likely needed this day
    # Goal: secure at least one unit of water if possible, but avoid overspending.
    # supply is between 15 and 25; one water unit corresponds to 9.
    possible_units = int(supply / float(WATER_REQ))  # safe int index-like usage
    if possible_units < 1:
        possible_units = 1

    # Base bid depends on HP and how long we've already been without water
    if hp <= 2 or no_water_days >= 2:
        urgency = 0.85
    elif hp <= 4:
        urgency = 0.65
    else:
        urgency = 0.52

    # Opponent pressure adjustment
    # Cindy/David were high; Eric/Alex were low/failed. If highest prev bid is very high, don't match it.
    if highest_prev_bid >= DAILY_SALARY * 1.35:
        pressure = 0.45
    elif highest_prev_bid >= DAILY_SALARY:
        pressure = 0.55
    else:
        pressure = 0.62

    # Supply scaling: when supply is higher, we can bid less and still expect to survive.
    if supply >= 22.0:
        supply_factor = 0.85
    elif supply <= 17.0:
        supply_factor = 1.05
    else:
        supply_factor = 0.95

    target = DAILY_SALARY * urgency * pressure * supply_factor

    # If yesterday bids were low overall, we can be slightly more aggressive to steal allocation.
    if avg_prev_bid < DAILY_SALARY * 0.6:
        target *= 1.08

    # Ensure we don't bid more than budget
    target = min(target, budget)

    # Hard caps for stability
    max_reasonable = DAILY_SALARY * 0.75
    if hp > 5 and no_water_days == 0:
        max_reasonable = DAILY_SALARY * 0.6
    target = min(target, max_reasonable)

    # If budget is tiny, bid what we can
    if target < 0.0:
        target = 0.0

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    # Default bid if no specific conditions met or no yesterday's bids
    bid_to_make = DAILY_SALARY * 0.55 # A moderate default bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85: # High competition threshold (127.5 for Cindy)
            if my_status['hp'] > 3: # Not critical (HP > 3), can be slightly less aggressive to save
                # Bid enough to potentially win, but don't overspend if not desperate
                bid_to_make = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.0) # Ensure it's at least 0.5 * salary
                bid_to_make = min(bid_to_make, DAILY_SALARY * 0.8) # Cap if HP is good (max 120)
            else: # Critical HP (<=3), must win
                bid_to_make = max(DAILY_SALARY * 0.95, highest_prev_bid + 5.0) # Very aggressive (min 142.5)
        else: # Moderate competition (highest_prev_bid < 127.5)
            # Bid slightly above to secure water, ensuring it's at least a moderate default
            bid_to_make = max(DAILY_SALARY * 0.55, highest_prev_bid + 1.5)

    # If no yesterday_bids, or if the above logic didn't set a higher bid,
    # and HP is critical, override with a high bid to prioritize survival.
    if my_status['hp'] <= 2: # Very critical HP
        bid_to_make = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 5 and bid_to_make < DAILY_SALARY * 0.8: # Low HP, ensure bid is at least 80% (120)
        bid_to_make = DAILY_SALARY * 0.8

    # Ensure bid is non-negative and within current budget
    return min(my_status['budget'], max(0.0, bid_to_make))
